        stageSaid: {
          left: stage.dataset.moreLeft,
          right: stage.dataset.moreRight,

/**
 * A map drawing itself, in a real browser, against a real server, **with no
 * model key at all**.
 *
 * It is the one thing no component test can claim: that a reviewer who has
 * configured nothing can open the first screen, press a card, and watch a map
 * build itself claim by claim — with a reserved rectangle standing where the next
 * claim will go, every proposal the rules refused on screen in the validator's
 * own words, and a receipt at the end saying what it cost.
 *
 * **It plays a recording, through the same route, the same eight events and the
 * same canvas a live run uses.** The only substitution anywhere is where the
 * bytes came from, which is what makes this evidence about the live route rather
 * than about a second one.
 *
 * **It skips itself when there is nothing recorded**, in one line saying so. The
 * recordings are made against a real key by the person who holds it; until one is
 * committed under `backend/recordings/`, this test has nothing to play and says
 * that rather than failing. The moment one lands it runs, with no change here.
 *
 * **Nothing below reads a value the screen has not settled on.** The waiting is
 * `waiting.ts`'s, the same helpers the stored example's test uses: a named signal
 * every time, never a sleep, and never `innerText` — which is empty until the
 * drawing library has measured a tile, and which is how a chip that plainly read
 * `.19` was once read as nothing at all.
 *
 * **A growing map needs one signal the stored one does not**, and it is the
 * reason this file has helpers of its own: on a stored map everything arrives at
 * once, and here the screen is *correct* and *incomplete* at the same moment for
 * minutes at a time. So every read below waits for the count it is about — this
 * many claims, this many rectangles, the receipt — rather than for the page.
 *
 * Nothing here is a number typed into this file. Every figure is read off the
 * screen and compared with itself across a change, or checked for its shape.
 */

import { expect, type Page, test } from "@playwright/test";
import { whereTheMapCameToRest, whereTheTileSits } from "./waiting.js";

/** The sentence the first screen's first card carries, as a reader would type it. */
const THE_SENTENCE = "The Strait of Hormuz is going to open next week.";

/**
 * How long a whole run is allowed to take before this test gives up on it.
 *
 * **A replay takes as long as its recording**, because the pacing is the
 * server's and the number of events is the file's — a twenty-proposal run is
 * four times the twenty seconds a five-proposal one takes, and neither number
 * is this test's to know. So the bound below is not a measurement and is not
 * tuned to a machine: it is generous on purpose, and exists only so that a run
 * which has genuinely stopped fails as a test rather than hanging.
 *
 * The default fifteen seconds is the wrong bound for exactly one thing in this
 * file — waiting for a run to finish — and the right one everywhere else, so it
 * is named here and used there.
 */
const A_WHOLE_RUN = 120_000;

// Every test here plays a recording from beginning to end, so each needs room
// for one. It is set on the file rather than in the configuration because it is
// a fact about these tests: the stored example's tests next door are right to
// be held to a minute.
test.describe.configure({ timeout: A_WHOLE_RUN + 60_000 });

/**
 * What this copy of the server says it can play back without a key.
 *
 * Asked of the server rather than read off the screen: whether this test has
 * anything to do at all is a fact about the server, and reading it off the page
 * would make the skip depend on the very screen being tested.
 */
async function whatCanBeReplayed(page: Page): Promise<{ example: string }[]> {
  const answer = await page.request.get("/api/readyz");
  const said = (await answer.json()) as { replayable?: { example: string }[] };
  return said.replayable ?? [];
}

/** What watching a whole run saw. */
interface WhatItSaw {
  /** True when, at some moment, a rectangle stood and not one claim had arrived. */
  readonly rectangleBeforeAnyClaim: boolean;
  /**
   * The words on the first rectangle, read at a moment when no claim had
   * arrived — so it is the one held open for the reader's own sentence and not
   * one of the frontier's, which carry *one step on from "…"*.
   *
   * Empty when no such moment was seen.
   */
  readonly firstRectangleSaid: string;
  /** The most rectangles that stood at once. */
  readonly mostRectangles: number;
  /**
   * True when, at some moment, two boxes on the map stood in the same place.
   *
   * The place they would share is the map's origin, where the hypothesis is:
   * a box the layout has not placed yet used to be drawn there, so every
   * arriving claim sat on top of the first one until the layout answered.
   */
  readonly everStacked: boolean;
  /**
   * How many rectangles stood at the moment each claim arrived, in order.
   *
   * The growing edge saying where the map is going, step by step, rather than
   * only at the start. **The last entry is allowed to be none**: the frontier
   * empties when the last claim closes, and no rectangle may stand where
   * nothing is coming.
   */
  readonly heldWhenEachClaimArrived: readonly number[];
  /**
   * How many claims were on the map, every time that number changed.
   *
   * The sequence rather than the largest of them: the largest is whatever the
   * map ended up with, which is a fact about the end and says nothing at all
   * about how the map got there. A map that appeared all at once and a map that
   * grew claim by claim have the same largest number and completely different
   * sequences.
   */
  readonly claimsWentOn: readonly number[];
  /**
   * How many claims were on the map the first time any likelihood appeared, and
   * how many appeared at that moment.
   *
   * Both are zero when none ever did. Together they are the statement that the
   * chips resolve **last** and **once**: the first number arrives when the map
   * is complete, and every other number arrives in the same breath.
   */
  readonly whenTheNumbersCame: { readonly claims: number; readonly numbers: number };
}

/** Where the page keeps what it has seen of itself. */
declare global {
  interface Window {
    theRecord?: WhatItSaw & { rectangleBeforeAnyClaim: boolean };
    stopWatching?: () => void;
  }
}

/**
 * Have the page start watching itself, before anything is asked for.
 *
 * **Four of the things this test is for are about a screen that is moving**, and
 * a moving screen cannot be checked by looking at it once: *a rectangle is drawn
 * before any claim*, *rectangles stand at the growing edge*, *the claims arrive
 * one at a time* and *not one likelihood is on screen until the map is finished*
 * are each true at some moments and false at others, and by the time an
 * assertion has been written the moment it was about is gone. Polling for one of
 * them races the run; asserting after it is over asserts about the wrong moment.
 *
 * So the page watches itself. Every change to the page is looked at — which is
 * every moment the screen was different — and what was on it is written down.
 * Nothing here sleeps, and nothing here can miss a moment that a poll would have
 * stepped over.
 *
 * **It is installed before the press**, and awaited, so that the very first
 * frame of the run is inside the record. Starting it after the press leaves the
 * one moment the first assertion is about — a rectangle standing with no claim
 * beside it — outside the window being watched, on a fast replay.
 *
 * @param page The page the map will be on.
 */
async function startWatching(page: Page): Promise<void> {
  await page.evaluate(() => {
    const record = {
      rectangleBeforeAnyClaim: false,
      firstRectangleSaid: "",
      mostRectangles: 0,
      everStacked: false,
      heldWhenEachClaimArrived: [] as number[],
      claimsWentOn: [] as number[],
      whenTheNumbersCame: { claims: 0, numbers: 0 },
    };
    window.theRecord = record;

    const look = (): void => {
      const held = document.querySelectorAll(".skeleton-tile").length;
      const claims = document.querySelectorAll(".tile").length;
      // A chip says on its own face whether it is showing a number or words,
      // and that is the marker to count: every chip renders a reading, and on
      // a growing map most of them are reading an absence out.
      const numbers = document.querySelectorAll('.belief-chip[data-reading="number"]').length;

      if (held > 0 && claims === 0) {
        record.rectangleBeforeAnyClaim = true;
        // **Read here, and never again from the live page.** What the first
        // rectangle says is true of one moment: the moment after it is drawn
        // and before the first claim replaces it with the frontier's. Reading
        // it in a second round trip asks a screen that has moved on — and on a
        // cold machine the whole run can finish in between, so the rectangle is
        // not merely different, it is gone.
        record.firstRectangleSaid = document.querySelector(".skeleton-tile")?.textContent ?? "";
      }
      record.mostRectangles = Math.max(record.mostRectangles, held);
      if (record.claimsWentOn[record.claimsWentOn.length - 1] !== claims) {
        // What the growing edge was saying at the moment this claim arrived.
        if (claims > 0) {
          record.heldWhenEachClaimArrived.push(held);
        }
        record.claimsWentOn.push(claims);
      }
      // Two boxes in one place. The place they would share is the map's origin,
      // where a box the layout has not placed yet used to be drawn.
      const places = [...document.querySelectorAll(".react-flow__node")].map(
        (one) => (one as HTMLElement).style.transform,
      );
      if (new Set(places).size !== places.length) {
        record.everStacked = true;
      }
      if (numbers > 0 && record.whenTheNumbersCame.numbers === 0) {
        record.whenTheNumbersCame = { claims, numbers };
      }
    };

    const watching = new MutationObserver(look);
    window.stopWatching = () => watching.disconnect();
    watching.observe(document.body, { subtree: true, childList: true, attributes: true });
    look();
  });
}

/**
 * Stop watching, and read back what the page saw of itself.
 *
 * **It waits for nothing.** The waiting is done by the named signals above it,
 * which is where a test that has to give up belongs: a watcher that settled on a
 * signal of its own would hang until the whole test timed out on a run that
 * broke, and the failure a reader saw would be *"test timed out"* rather than
 * *"the run said it failed"*.
 *
 * @param page The page the map is on.
 */

/**
 * Turning a world into the tiles and wires the canvas draws.
 *
 * One function, no arithmetic, and nothing invented: every tile below stands
 * for a claim the server sent, every wire for an arrow the server sent, and the
 * only judgement made here is which tiles there is room to draw.
 */

import type { Node } from "@xyflow/react";
import type { ClaimView, WorldView } from "../world";
import { NOT_ON_THIS_MAP } from "../world/naming";
import type { LayoutEdge, LayoutTile } from "./elkGraph";
import { TILE_MIN_HEIGHT, TILE_WIDTH, tileHeight } from "./geometry";
import { assignLayers, capLayers } from "./layers";
import { portsForAWire, portsOf } from "./ports";
import type { CausalEdge } from "./wires/CausalWire";

/** A tile standing for one claim. */
export type ClaimNode = Node<
  { claim: ClaimView; isHypothesis: boolean; versions?: number; height: number },
  "claim"
>;

/** A tile standing for the claims a column had no room for. */
export type OverflowNode = Node<{ count: number }, "overflow">;

/** A rectangle held open where a claim is about to arrive. Never a claim. */
export type SkeletonNode = Node<{ words: string }, "skeleton">;

/** Everything the canvas draws as a box. */
export type MapNode = ClaimNode | OverflowNode | SkeletonNode;

/**
 * One rectangle the map is holding open, reduced to what drawing one needs.
 *
 * Stated here rather than imported from the reducer that produces them, so that
 * the picture depends on no part of the machinery that reads a stream: this is
 * the whole of what the canvas needs to know about a thing that is not a claim.
 */
export interface ReservedBox {
  /** The rectangle's name. A box's name, never a claim's. */
  readonly id: string;
  /** The one line it carries. */
  readonly words: string;
  /** The open claim it hangs off, so the layout puts it one column further right. */
  readonly after: string | null;
}

/**
 * A wire, carrying everything it needs to say its five things at once.
 *
 * How it is routed is filled in by the canvas rather than here: a wire that has
 * to skip a column needs to know where the other tiles ended up, and only the
 * canvas knows that.
 */
export type MapEdge = CausalEdge;

/** What the canvas needs in order to draw a world. */
export interface MapDrawing {
  /** The tiles, without positions — those come from the layout. */
  readonly nodes: readonly MapNode[];
  /** The wires, as they will be drawn. */
  readonly edges: readonly MapEdge[];
  /**
   * Every tile with the height it will be drawn at, which is the height the
   * layout reserves for it. One number, worked out once, used by both.
   */
  readonly tiles: readonly LayoutTile[];
  /**
   * The arrows the layout gets a look at.
   *
   * Not the same list as the wires. Feedback arrows are left out, because a
   * left-to-right order cannot be worked out from a map with a loop in it, and
   * an arrow that stands in for collapsed tiles is put in, so the collapsed tile
   * lands in the column it belongs to.
   */
  readonly layoutEdges: readonly LayoutEdge[];
}

/**
 * What the tile standing in for a column's collapsed claims is called.
 *
 * The canvas reads the column back out of it, so that activating one of those
 * tiles can open the outline filtered to that column — the claims behind it
 * already have items there, and the tile only has to point at them.
 */
export const OVERFLOW_PREFIX = "more-in-column-";

/** The identifier of the tile standing in for a column's collapsed claims. */
function overflowId(layer: number): string {
  return `${OVERFLOW_PREFIX}${layer}`;
}

/**
 * What every reserved rectangle's name starts with.
 *
 * It is how the canvas tells a box from a claim without asking the reducer:
 * nothing may be selected, focused or asked about under one of these names,
 * because there is nothing there yet.
 */
export const RESERVED_PREFIX = "skeleton:";

/**
 * Work out the tiles, the wires, and what the layout gets to see.
 *
 * @param world The world as the source handed it over.
 * @param heights How tall each tile is to be drawn, when something outside knows
 *   better than this claim alone does. A diff draws two worlds in one coordinate
 *   space, and a claim can need more room in one of them than in the other — it
 *   grows badges when an edit touched it — so the box is reserved for the taller
 *   of the two and neither painting moves anything. Left out, each tile is as
 *   tall as its own content.
 * @param reserved The rectangles being held open at the growing edge of a map
 *   that is still being built. Empty on every finished map. Each one is drawn at
 *   a tile's floor height and is pulled into the column after the claim it hangs
 *   off by an arrow the layout sees and nobody draws — the same trick the tile
 *   standing in for a full column already uses.
 */
export function toFlow(
  world: WorldView,
  heights?: ReadonlyMap<string, number>,
  reserved: readonly ReservedBox[] = [],
): MapDrawing {
  const ids = world.claims.map((claim) => claim.id);
  const { shown, overflows } = capLayers(assignLayers(ids, world.links));
  const drawn = new Set(shown.map((one) => one.id));
  const byId = new Map(world.claims.map((claim) => [claim.id, claim]));

  const nodes: MapNode[] = [];
  for (const placed of shown) {
    const claim = byId.get(placed.id);
    if (claim === undefined) {
      continue;
    }
    nodes.push({
      id: claim.id,
      type: "claim",
      position: { x: 0, y: 0 },
      draggable: false,
      data: {
        claim,
        isHypothesis: claim.id === world.hypothesisId,
        versions: world.versions,
        height: heights?.get(claim.id) ?? tileHeight(claim),
      },
    });
  }
  for (const overflow of overflows) {
    nodes.push({
      id: overflowId(overflow.layer),
      type: "overflow",
      position: { x: 0, y: 0 },
      draggable: false,
      data: { count: overflow.count },
    });
  }

  // Only arrows between two tiles that are actually drawn become wires. An
  // arrow into a collapsed claim has nowhere to land, and the collapsed tile
  // says in words that those claims are still on the map.
  const claimWords = new Map(world.claims.map((claim) => [claim.id, claim.claim]));
  const edges: MapEdge[] = world.links
    .filter((link) => drawn.has(link.source) && drawn.has(link.target))
    .map((link) => {
      const { source, target } = portsForAWire(link.mode);
      return {
        id: link.id,
        source: link.source,
        target: link.target,
        sourceHandle: source,
        targetHandle: target,
        // One kind of wire, drawn by us. How it gets from one end to the other
        // is worked out by the canvas, which is the only thing that knows where
        // the other tiles ended up.
        type: "causal" as const,
        // What a reader who never sees the picture hears instead. Everything
        // the stroke says, said in words.
        ariaLabel:
          `arrow from ${claimWords.get(link.source) ?? NOT_ON_THIS_MAP} ` +
          `to ${claimWords.get(link.target) ?? NOT_ON_THIS_MAP}`,
        data: {
          shape: link.shape,
          strength: link.strength,
          mode: link.mode,
          lag: link.lag,
          reflexive: link.reflexive,
          provenance: link.provenance,
          conditional: link.conditional,
        },
      };
    });

  // What the layout sees. Feedback arrows are set aside: an arrow that points
  // backwards cannot help decide what comes first, and leaving it in would make
  // the map a loop with no beginning.
  const layoutEdges: LayoutEdge[] = world.links
    .filter((link) => !link.reflexive && drawn.has(link.source) && drawn.has(link.target))
    .map((link) => ({ id: link.id, source: link.source, target: link.target }));

  // The collapsed tile is pulled into the right column by the same arrows that
  // would have reached the claims it stands for. These are never drawn.
  for (const overflow of overflows) {
    const hidden = new Set(overflow.hidden);
    const causes = new Set(
      world.links
        .filter((link) => !link.reflexive && hidden.has(link.target) && drawn.has(link.source))
        .map((link) => link.source),
    );
    for (const cause of causes) {
      layoutEdges.push({
        id: `standing-in:${cause}->${overflowId(overflow.layer)}`,
        source: cause,
        target: overflowId(overflow.layer),
      });
    }
  }

  // The rectangles held open at the growing edge. They are boxes, not claims:
  // they never join `world.claims`, never reach the network, and carry nothing a
  // reader could mistake for a reading. Each is pulled into the column after the
  // claim it hangs off by an arrow the layout sees and nobody draws.
  for (const box of reserved) {
    nodes.push({
      id: box.id,
      type: "skeleton",
      position: { x: 0, y: 0 },
      draggable: false,
      // A rectangle is not a thing you can be on or ask about: it stands for a
      // claim that does not exist yet, and there is nothing to read out.
      selectable: false,
      focusable: false,
      data: { words: box.words },
    });
    if (box.after !== null && drawn.has(box.after)) {
      layoutEdges.push({
        id: `holding-open:${box.after}->${box.id}`,
        source: box.after,
        target: box.id,
      });
    }
  }

  // **Every tile is told how big it is and where its ports are, and the layout,
  // the tile and the drawing library are all told the same numbers.**
  //
  // A tile's box is not something to be discovered: it is 280 pixels wide
  // (`TILE_WIDTH`) and exactly as tall as the height this file worked out from
  // the claim, and the components draw themselves at precisely that size. The
  // layout engine has always been told. The drawing library was not — it was
  // left to measure each tile with a `ResizeObserver`, and **it draws nothing
  // it has not measured**: a node with no size is rendered `visibility:
  // hidden`, and a wire with no measured port at either end is not rendered at
  // all.
  //
  // That is a promise the browser does not keep. When too many size
  // observations fall due in one frame the browser abandons the rest of them —
  // *"a ResizeObserver loop completed with undelivered notifications"* — and an
  // abandoned one is never delivered. A tile whose box then never changes size
  // again is never observed again, so it stays invisible for the life of the
  // page, and its arrows stay off the glass for the life of the page: the map
  // holds its claims, in their places, and says nothing about how they are
  // joined. Both halves are reachable today, on a busy machine, on the stored
  // example.
  //
  // Saying it is not a guess and not a duplicate: it is the one set of numbers,
  // handed to every thing that needs them, from the one place that worked them
  // out. A port's box comes from `ports.ts`, which is also what the tile writes
  // onto the element it draws — so what is declared here is what the browser
  // would have measured, and the library correcting itself afterwards from its
  // own measurement changes nothing. Nothing downstream reads any of it back.
  //
  // **A reserved rectangle says how big it is too**, and it is the box that
  // needs saying most: it stands where a claim is about to arrive, so it is on
  // screen at the exact moment the page is busiest and the browser is likeliest
  // to drop an observation — and a rectangle nobody can see is a growing edge
  // that has stopped saying where the map is going. It declares no port: nothing
  // is at the end of an arrow until the claim itself arrives.
  const tiles: LayoutTile[] = [];
  const sized = nodes.map((node) => {
    const height = node.type === "claim" ? node.data.height : TILE_MIN_HEIGHT;
    tiles.push({ id: node.id, height });
    const box = { ...node, initialWidth: TILE_WIDTH, initialHeight: height };
    // Only a claim's tile has ports, because only a claim is ever at the end of
    // an arrow. The tile standing in for a column's collapsed claims has none,
    // and neither has a rectangle held open where a claim is about to arrive:
    // both are told none rather than told the wrong ones.
    return node.type === "claim" ? { ...box, handles: portsOf(height) } : box;
  }) as MapNode[];

  return { nodes: sized, edges, layoutEdges, tiles };
}

