/**
 * Work out what the map draws.
 *
 * @param boxes Every box the map holds, in reading order.
 * @param places Where the layout has said each box goes. Empty until it answers.
 * @param holding What this returned last time it was asked, so the box standing
 *   at the origin is the one that was put there.
 */
export function whatIsOnTheGlass(
  boxes: readonly MapNode[],
  places: ReadonlyMap<string, Position>,
  holding: MapNode | null,
): OnTheGlass {
  const nothingIsPlaced = places.size === 0;
  const drawn = boxes.flatMap((box, place) => {
    const at = places.get(box.id) ?? (nothingIsPlaced && place === 0 ? THE_ORIGIN : undefined);
    return at === undefined ? [] : [{ ...box, position: at }];
  });
  return { boxes: drawn, holding: holding };
}

input.new_string:
/**
 * Work out what the map draws.
 *
 * Three rules, and the third is the one that was missing.
 *
 * **A box is drawn where the layout put it.** Nowhere else. A box the layout has
 * not placed has no place, and drawing it at the map's origin gives it one the
 * layout never agreed to — so it appears at the origin and then hops to wherever
 * the layout actually wanted it, on the one screen whose whole promise is that
 * nothing already drawn ever moves.
 *
 * **Except the first, and the first is a rectangle.** Before the layout has
 * answered even once the origin is nobody's place: there is nothing to be drawn
 * on top of, and a generation's first paint may not be an empty stage
 * (INV-workbench.61 — a reserved rectangle is on screen before the first proposal
 * comes back). The box that takes it is the rectangle held open for the reader's
 * own sentence, which is the only box on the map at that moment, and never a
 * claim.
 *
 * **And it stays there until the layout answers.** The claim that rectangle
 * stands for can arrive before the first answer does — on a slow machine it
 * routinely does, because `useLayout` throws away an answer whose map changed
 * underneath it, so the race is lost and started again. Taking the rectangle
 * down then would leave the map with a claim on it and no rectangle anywhere:
 * a growing map that, for as long as the layout takes, has stopped saying where
 * it is going. So the rectangle keeps the origin, the claim waits for its own
 * place, and the two swap in one frame when the layout answers — which is
 * exactly what a reserved rectangle is for.
 *
 * @param boxes Every box the map holds, in reading order.
 * @param places Where the layout has said each box goes. Empty until it answers.
 * @param holding What this returned last time it was asked, so the box standing
 *   at the origin is the one that was put there and not whichever box happens to
 *   be first now.
 */
export function whatIsOnTheGlass(
  boxes: readonly MapNode[],
  places: ReadonlyMap<string, Position>,
  holding: MapNode | null,
): OnTheGlass {
  if (places.size > 0) {
    return {
      boxes: boxes.flatMap((box) => {
        const at = places.get(box.id);
        return at === undefined ? [] : [{ ...box, position: at }];
      }),
      holding: null,
    };
  }
  // The layout has placed nothing at all. One box stands, at the origin: the one
  // already standing there, or — the first time anything is asked — the map's
  // first reserved rectangle. A map with no rectangles at all is a finished one
  // arriving, and it waits.
  const standing = holding ?? boxes.find((box) => box.type === "skeleton") ?? null;
  return {
    boxes: standing === null ? [] : [{ ...standing, position: THE_ORIGIN }],
    holding: standing,
  };
}

